from hashlib import sha256
from threading import get_ident

from .primary_main_material_getter import _convert, _equal, _pair_control, _phi, _pointer, _single_control, _switch, _read_pair_control
from .primary_main_mix import MAIN_SHA256
from .primary_vm import PrimaryVM, PrimaryProgramLimit, PrimarySemanticUnavailable


PREFIX_ENTRIES = frozenset(((1, 0, None, True), (32266, 688, 680, False),
                            (32266, 688, 689, False), (32266, 688, 711, False)))
PREFIX_EXITS = {1: 31440, 32266: 36986}


class Main408Observation:
    def __init__(self, runtime, callback):
        from .primary_sign import PrimaryRuntime
        if type(runtime) is not PrimaryRuntime or not callable(callback):
            raise PrimarySemanticUnavailable('Main408 observation requires its exact runtime and callback')
        self.runtime, self.callback = runtime, callback
        self.thread = get_ident()
        self.active = False
        self.status = 'NOT_OBSERVED'

    def __enter__(self):
        if self.active or self.thread != get_ident() or getattr(self.runtime, '_main408_observation', None) is not None:
            raise PrimarySemanticUnavailable('Main408 observation binding is unavailable')
        self.runtime._main408_observation = self
        self.active = True
        return self

    def __exit__(self, kind, error, trace):
        if getattr(self.runtime, '_main408_observation', None) is self:
            del self.runtime._main408_observation
        else:
            self.status = 'COMPETING_BINDING'
        self.active = False

    def observe(self, vm):
        try:
            from .primary_sign_lifecycle import _PublicDirectOwner
            runtime = self.runtime
            owner = getattr(runtime, '_active_main', None)
            public = getattr(runtime, '_primary_public_direct_owner', None)
            if (not self.active or self.status != 'NOT_OBSERVED' or self.thread != get_ident() or
                    getattr(runtime, '_main408_observation', None) is not self or
                    type(vm) is not PrimaryVM or vm.runtime is not runtime or vm.memory is not runtime.memory or
                    vm.image_base != runtime.image_base or sha256(vm.program.raw).hexdigest() != MAIN_SHA256 or
                    type(owner) is not dict or owner.get('vm') is not vm or owner.get('thread') != self.thread or
                    owner.get('generation') != runtime._main_generation or runtime._execute_thread != self.thread or
                    runtime._active_failed or type(public) is not _PublicDirectOwner or public.runtime is not runtime or
                    not public.valid()):
                return
            self.status = 'ATTEMPTED'
            self.callback(runtime)
            self.status = 'OBSERVED'
        except BaseException:
            self.status = 'OBSERVER_FAILED'


def execute_primary_main_prefix(vm, *, charge=None):
    if (type(vm) is not PrimaryVM or sha256(vm.program.raw).hexdigest() != MAIN_SHA256 or
            (vm.pc, vm.block, vm.predecessor, vm.initial_block) not in PREFIX_ENTRIES):
        raise PrimarySemanticUnavailable('independent Main prefix requires its fixed entry')
    runtime = vm.runtime
    owner = getattr(runtime, '_active_main', None)
    if (runtime is None or vm.memory is not runtime.memory or vm.image_base != runtime.image_base or
            type(owner) is not dict or owner.get('vm') is not vm or owner.get('thread') != get_ident() or
            owner.get('generation') != runtime._main_generation or runtime._execute_thread != get_ident() or
            runtime._active_failed or getattr(runtime, '_consumed_mgf', None) is not None or
            len(runtime._program_calls) != 1 or runtime._program_calls[0]['name'] != 'main' or
            runtime._program_calls[0]['hosts'] is not None):
        raise PrimarySemanticUnavailable('independent Main prefix requires the current owner without replay')
    if vm.halted or vm.abort_reason is not None or any(getattr(vm, name) is not None for name in
            ('pending_once10', 'pending_once9', 'pending_l26', 'pending_variadic', 'pending_native',
             'private_iv_native_pending')):
        raise PrimarySemanticUnavailable('independent Main prefix cannot enter a stopped or pending body')
    if vm.pc == 1 and vm.arena_used != 0:
        raise PrimarySemanticUnavailable('independent Main prefix requires a fresh Main arena')
    entry = vm.pc
    state = dict(entryWord=entry, exitWord=PREFIX_EXITS[entry], backend='DIRECT_MAIN_PREFIX',
                 referenceRecordCount=0, completed=False, earlyReturn=False, traceComplete=False,
                 completeIndependentMain=False, final96Qualified=False,
                 childBackend='EXISTING_RUNTIME_HOSTS_WITH_RESIDUAL_GENERIC_CHILDREN')
    vm.primary_main_prefix_state = state
    def tick(word):
        if vm.abort_reason is not None:
            raise PrimaryProgramLimit('active VM was aborted: ' + vm.abort_reason)
        if charge is not None:
            charge()
        state['referenceRecordCount'] += 1
        vm.pc = word + 1
    if entry == 1:
        _prefix_one(vm, tick)
    else:
        _prefix_two(vm, tick)
    state['completed'] = True
    state['earlyReturn'] = vm.halted
    state['exitWord'] = vm.pc
    return state


def _prefix_host(vm, word, callee, arguments, signature, destination):
    address = vm.cells.value(callee)
    vm.host_calls.append((word, address, arguments, signature))
    from .primary_sign import _invoke_host
    result = _invoke_host(vm, address, arguments, signature,
                          argument_types=vm.program.type(signature).parameters[3:])
    owner = getattr(vm.runtime, '_active_main', None)
    if (owner is not None and owner['vm'] is vm and word in (11562, 11569) and
            vm.block == 277 and callee == 1719 and address == vm.image_base + 0x3E97020 and
            signature == 152 and destination == (1718 if word == 11562 else 1720) and arguments == (1717,)):
        from .primary_sign_lifecycle import region_at
        region = region_at(vm.memory, result)
        if not result or region is None or result not in vm.runtime.allocations:
            raise PrimaryProgramLimit('approved main temporary allocation lacks its exact owner')
        vm.main_owned_allocations.append(dict(pointer=result, region=region,
                                               size=vm.runtime.allocations[result], generation=owner['generation'],
                                               word=word, destination=destination))
    if ((word, callee, arguments, signature, destination) == (408, 147, (), 101, 146) and
            address == vm.image_base + 0x3592167):
        observation = getattr(vm.runtime, '_main408_observation', None)
        if type(observation) is Main408Observation:
            observation.observe(vm)
    if destination is not None:
        vm._write(destination, result, 8, 'high.native_result_q')
    if (word, callee, arguments, signature, destination) in ((2353, 454, (), 129, 453), (5821, 454, (), 129, 936)):
        from .primary_main_stage_observation import observe_main_stage
        observe_main_stage(vm, word)


def _prefix_variadic(vm, word, end, signature, destination, callee, types, arguments):
    state = dict(phase='header', abi=1, callee_reads=0, prepare_calls=0, return_stores=0)
    vm.variadic_state = state
    if vm.memory.load(vm.image_base + 0x677E1BC, 4) == 0x80000000:
        vm.pc += 3
        raise PrimarySemanticUnavailable('independent Main prefix variadic alternate header is unavailable')
    vm.pc = word + 5
    if _read_pair_control(vm):
        vm.pc += 2
        raise PrimarySemanticUnavailable('independent Main prefix variadic alternate callee is unavailable')
    state['phase'] = 'callee'
    vm.pc = word + 7
    state['callee_reads'] += 1
    _single_control(vm)
    state['phase'] = 'arguments'
    vm.pc = end
    state['phase'] = 'prepare'
    _single_control(vm)
    state['prepare_calls'] += 1
    _pair_control(vm)
    state['phase'] = 'call'
    address = vm.memory.load(vm.cells.pointer(callee), 8)
    vm.host_calls.append((word, address, arguments, signature))
    from .primary_sign import _invoke_host
    result = _invoke_host(vm, address, arguments, signature, argument_types=types)
    state['phase'] = 'return_wait'
    if vm.memory.load(vm.image_base + 0x677E1BC, 4) == 0x80000000:
        raise PrimarySemanticUnavailable('independent Main prefix variadic return wait is unavailable')
    state['phase'] = 'store'
    vm._write(destination, result, 8, 'high.variadic_result_q')
    state['return_stores'] += 1
    if vm.memory.load(vm.image_base + 0x677E1BC, 4) == 0x80000000:
        raise PrimarySemanticUnavailable('independent Main prefix variadic duplicate return wait is unavailable')
    state['phase'] = 'complete'



